import { Launchpage } from "Hindi-olabsnxtg-library";
import { useTranslation } from "react-i18next";
import ActStartPopupContent from "./ActStartPopupContent";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import Swal from "sweetalert2";
import React, { useEffect } from "react";

export const Ll5_launchpage = () => {
  const isMobile = /Mobi|Android/i.test(navigator.userAgent);
  var arr = ["Students will be able to use the prefix and suffix with a word."];
  useEffect(() => {
    if (isMobile) {
      // alert("Please play a game in landscape mode for better user experience.");
      Swal.fire({
        text: "Please play a game in landscape mode for better user experience.",
      });
    }
  }, []);
  const { t, i18n } = useTranslation();
  var arr = [
    "छात्र विभिन्न प्रकार के उपसर्ग प्रत्यय को जोड़कर कर नए शब्दों की पहचान करने में सक्षम होंगे।",
  ];
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });

  ReactGA.send({
    hitType: "pageview",
    page: "L5/",
    title: "L5 | Launchpage_open",
  });

  return (
    <Launchpage
      L_title="उपसर्ग प्रत्यय"
      L_objective={t("Objective")}
      L_act_objective={t("उपसर्ग और प्रत्यय का उपयोग करना।")}
      L_array={arr}
      L_learning_outcome={t("learning_out_title")}
      L_startbutton={t("start")}
      L_actstartPopup_content_comp={<ActStartPopupContent />}
      L_actstartPopup_content_title={t("what_we_are_going_to_learn_title")}
      L_ok="हाँ"
      L_cancel="रद्द करें"
      WS_sendJsonMessage={sendJsonMessage}
      WS_sendLogData={SendLogData}
      L_labName="उपसर्ग प्रत्यय"
      L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-03"
    
    />
  );
};
