import React, { createContext, useRef, useEffect, useState } from "react";
import { Link, Navigate, useNavigate } from "react-router-dom";
import * as Instru from "../components/Instruction";
import BackNextBar from "../components/BackNextBar";
import { Translation, useTranslation } from "react-i18next";
import play from "../Img/play.png";
import "../styles/styles.css";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";

function LevelstartMidContent({}) {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const txt = useRef(0);
  var flag = "0"; //landscape

  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});
  const [pageName, setPageName] = useState("level_startpage");
  useEffect(() => {
    //Runs on every render
  });

  const handlelevel1 = () => {
    //log
    SendLogData(
      sendJsonMessage,
      pageName,
      "level_start",
      "Clicked",
      "Click on level button"
    )


    //GA
    ReactGA.event({
      action: "L5 | level_start",
      category: "L5 | Level_one_button_clicked",
      label: "Level_one_button_clicked",
    });

    navigate("/sangya-lab/ll5_level1");
  };
  const handlelevel2 = () => {
    navigate("sangya-lab/ll5_level_2");
  };
  const handlelevel3 = () => {
    navigate("/sangya-lab/levelthree");
  };
  return (
    <div
      className=" d-flex justify-content-center align-items-center"
      style={{ height: "100%" }}
    >
      <div
        className="d-flex justify-content-center align-items-center"
        style={{
          height: "90%",
          fontSize: "1rem",
          overflow: "auto",
          overflowX: "hidden",
          // overflowY: "hidden",
        }}
      >
        <div className="row d-flex justify-content-around " style={{}}>
        
          <div
            className="row level2col bg-danger"
            style={{
              borderRadius: "10px",
              backgroundColor: "#D2CDCD",
              width: "65%",
            }}
          >
            <h5 className="text-center" style={{ color: "#FFFFFF" }}>
              स्तर 1
            </h5>
            <div className="d-flex justify-content-center align-items-center">
              <img
                className=""
                src={play}
                alt="Logo"
                onClick={handlelevel1}
              ></img>
            </div>
            <h5
              className="text-center"
              style={{ marginTop: "5%", color: "#FFFFFF" }}
            >
              संज्ञा
            </h5>
          </div>
          {/* <div
            className="row level3col"
            style={{
              borderRadius: "10px",
              backgroundColor: "#D2CDCD",
              width: "30%",
            }}
          >
            <h5 className="text-center" style={{ color: "#FFFFFF" }}>
              स्तर २
            </h5>
            <div className="d-flex justify-content-center align-items-center">
              <img
                className=""
                src={play}
                alt="Logo"
                onClick={handlelevel2}
              ></img>
            </div>
            <h5
              className="text-center"
              style={{ marginTop: "5%", color: "#FFFFFF" }}
            >
              विशेषण पर अनुच्छेद
            </h5>
          </div> */}
        </div>
      </div>
    </div>
  );
}

export default LevelstartMidContent;
