import React from "react";
import { Route, Routes, useParams } from "react-router-dom";
import ActStartPopupContent from "./components/ActStartPopupContent";
import { useTranslation } from "react-i18next";
import { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { changeLang } from "./store/Store";
import Language from "./Language";
import "../src/App.css";
import { Ll5_launchpage } from "./components/Ll5_launchpage";
import LL5_theory from "./components/LL5_theory";
import Ll5_procedure from "./components/Ll5_procedure";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "./config/dbconfig.js";
import { browserName, browserVersion } from "react-device-detect";
import { v4 as uuid } from "uuid";
import axios from "axios";
import Ll5_level3 from "./components/Ll5_level3.js";
import Ll5_level_1 from "./components/Ll5_level_1.js";
import Ll5_level_2 from "./components/Ll5_level_2.js";
import Ll5_level_3 from "./components/Ll5_level_3.js";
import { L_QuizComponent } from "./quiz/L_QuizComponent";
import L_HelpComponent from "./Help/L_HelpComponent.js";
import { Help } from "Hindi-olabsnxtg-library";

const App = () => {
  const { t, i18n } = useTranslation();
  const { id } = useParams();
  let dispatch = useDispatch();
  let { firstStore } = useSelector((globalState) => globalState);

  // ****** log ********

  const [ip, setIP] = useState("");
  const sid = uuid();

  useEffect(() => {
    localStorage.setItem("sessionid", sid);
  }, []);

  useEffect(() => {
    // to call get data function which return ip address
    getData();
  }, [ip]);

  //creating function to load ip address from the API
  const getData = async () => {
    const res = await axios.get("https://api.ipify.org/?format=json");
    //console.log(res.data);
    setIP(res.data.ip);
    localStorage.setItem("clientip", ip);
  };

  const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
    onOpen: () => {
      console.log("WebSocket connection established.");
    },
    onError: () => {
      console.log("WebSocket connection Error");
    },
    share: true,
    filter: () => false,
    retryOnError: true,
    shouldReconnect: () => true,
  });

  // *******  GA ********
  useEffect(() => {
    ReactGA.initialize("G-EH0V4FKWYX", {
      gaOptions: {
        gtag: true,
      },
    });
  }, []);

  useEffect(() => {
    //console.log("parameter id " + firstStore?.lang);

    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hn") {
      alert("in app hn : ", id);
      i18n.changeLanguage("hn");
      dispatch(changeLang("hn"));
    }
  }, []);
  return (
    <Routes>
      {/* <Route path="/" element={<Launchpage />} /> */}
      <Route path="/" element={<Ll5_launchpage />} />
      <Route path="/lang=:id" element={<App />} />
      <Route path="/procedure_page" element={<Ll5_procedure />} />
      <Route path="/letusverify" element={<Ll5_level_1 />} />
      <Route path="/level2" element={<Ll5_level_2 />} />
      <Route path="/level3" element={<Ll5_level_3 />} />
      <Route path="/sangya-lab/ll5_levelfinal" element={<Ll5_level3 />} />
      <Route path="/theory_page" element={<LL5_theory />} />
      <Route path="/help_page" element={<L_HelpComponent />} />
      <Route path="/quiz" element={<L_QuizComponent />} />
      <Route path="/letusverify/help" element={<Help />} />
    </Routes>
  );
};

export default App;
