import { Theory } from 'Hindi-olabsnxtg-library';
import React from 'react'
import AltheoryMidContent1 from '../components/AltheoryMidContent1'
import QuizPopupContent from '../quiz/QuizPopupContent';
import useWebSocket, { ReadyState } from 'react-use-websocket';
import logconfig from '../config/dbconfig.js';
import {SendLogData} from "../config/wslog.js"
import ReactGA from "react-ga4";
import { useTranslation } from 'react-i18next';

const LL5_theory = () => {
  const { t, i18n } = useTranslation();  
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});

     // ********GA***********
     ReactGA.send({
      hitType: "pageview",
      page: "L5/sangya-lab/theorey",
      title: "L5 | theory_of_sangya",
    });

  return (
    <div>
    <Theory
        H_title="उपसर्ग प्रत्यय"
        H_sidebarvisible="false"
        HQ_quittext="क्या आप निश्चित हैं, आपकी बाहर निकलने की इच्छा है?"
        HQ_yes="हाँ।"
        HQ_cancel="रद्द करें।"
        RSM_QuizPopupContent_comp={<QuizPopupContent/>}                  // here you have to add instructio of quiz (you can make a component and add it here)
        RSM_Intruc_popup_title_string="प्रश्नोत्तरी के लिए निर्देश हैं।"
        RSM_ok="हाँ"
        RSM_theory_tt={t("theory")}
        RSM_vivavoce_tt={t("vivavoce")}
        RSM_procedure_tt={t("procedure")}  
        RSM_help_tt={t("help")}   
        RSM_menu_tt={t("menu")}  
        TT_midheight="90%"
        WS_sendJsonMessage={sendJsonMessage}
        WS_sendLogData={SendLogData}
        L_labName="उपसर्ग प्रत्यय"
        L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-03"  
        TT_midcontent_comp={<AltheoryMidContent1/>}                                                             // here you have to add Theory (you can make a component and add it here)
  
        //workbenchlabel="this is workbench lebel"
      />
    </div>
  )
}

export default LL5_theory
